"""Money helpers for the ledger example."""

from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


def to_cents(value: Decimal) -> Decimal:
    """Round a decimal amount to whole cents."""
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def prorate(amount: Decimal, days_used: int, days_in_period: int) -> Decimal:
    """Share of ``amount`` for ``days_used`` out of ``days_in_period`` days.

    Raises ValueError when the period is empty or the usage exceeds it.
    """
    if days_in_period <= 0:
        raise ValueError("empty billing period")
    if not 0 <= days_used <= days_in_period:
        raise ValueError("days_used outside the period")
    return to_cents(amount * Decimal(days_used) / Decimal(days_in_period))

