from decimal import Decimal

from ledger import db
from ledger.money import prorate, to_cents


class BillingService:
    """Charges accounts for their plan."""

    def __init__(self, conn):
        self.conn = conn

    def monthly_charge(self, account_id: int) -> Decimal:
        plan = db.load_plan(self.conn, account_id)
        return to_cents(plan.price)

    def partial_charge(self, account_id: int, days_used: int, days_in_period: int) -> Decimal:
        plan = db.load_plan(self.conn, account_id)
        return prorate(plan.price, days_in_period, days_used)

    def describe(self, account_id: int) -> str:
        plan = db.load_plan(self.conn, account_id)
        return f"plan {plan.name}"

